	SCI3_SMR_MP = 0x4
	// Disable multi-processor communications function
	SCI3_SMR_MP_0 = 0x0
	// Enable multi-processor communications function
	SCI3_SMR_MP_1 = 0x1
	// Position of STOP field.
	SCI3_SMR_STOP_Pos = 0x3
	// Bit mask of STOP field.
	SCI3_SMR_STOP_Msk = 0x8
