	// PCLK/16 clock (n = 2)
	SCI3_SMR_SMCI_CKS_10 = 0x2
	// PCLK/64 clock (n = 3)
	SCI3_SMR_SMCI_CKS_11 = 0x3
	// Position of BCP field.
	SCI3_SMR_SMCI_BCP_Pos = 0x2
	// Bit mask of BCP field.
	SCI3_SMR_SMCI_BCP_Msk = 0xc
